-- Generated by tools/prepare_story.py from docs/story.md; edit the reviewed script.
return {
    {key="before-01", phase="before", level=1, lines={
        {"noelle", "Excuse me, sir, I'm looking for Gran's house on the square. The key's \"somewhere\"."},
        {"wren", "Somewhere's nearer than it sounds. Mind your third step, miss. It's a sly one."},
        {"agnes", "Rosa's granddaughter! Spare room's yours. Now, can you get a light up from the station by dark?"},
    }},
    {key="after-01", phase="after", level=1, lines={
        {"noelle", "Agnes, look up! Gran says leave a light on for one more. Can they see us from the station?"},
        {"theo", "Very nice. Your arch is in my way. That's where I sell my firs."},
        {"noelle", "Then share the corner, Theo. Have a mulled wine. Cloves, cinnamon, orange peel."},
    }},
    {key="after-02", phase="after", level=2, lines={
        {"noelle", "Theo, I need fresh boughs for the wreath. Four candles, one lit every Sunday. Can you spare any?"},
        {"theo", "Mind the resin. It gets on everything, even my letters."},
        {"noelle", "Your receipt's welded to my mitten. Is that part of the deal?"},
    }},
    {key="after-03", phase="after", level=3, lines={
        {"pip", "Mrs Holt, Mrs Alder's put candles in every window, and Mr Strand says your chimney smokes!"},
        {"agnes", "Tell that man it's a free sky. We've not spoken in forty years, love."},
        {"noelle", "Forty years, and he still checks your chimney? Agnes, who is Mr Strand to you?"},
    }},
    {key="after-04", phase="after", level=4, lines={
        {"pip", "Noelle, tie a wish ribbon! Careful, Bramble, Mr Finch's goat, has eaten two already!"},
        {"agnes", "Rosa kept every ribbon tied here in a biscuit tin. Go on, love, tie one."},
        {"noelle", "I tied one at six, with Gran. It's only till Christmas, Agnes. Does a ribbon still count?"},
    }},
    {key="after-05", phase="after", level=5, lines={
        {"pip", "Noelle, someone hung a box on the lamp post! Take a note, leave a note. You never ask who."},
        {"noelle", "Then here's mine, Pip. \"Dear anyone. Is there a trick to getting people to let you help?\""},
    }},
    {key="after-06", phase="after", level=6, lines={
        {"noelle", "Pip, I asked how to get help! \"Start by sitting down with someone. Stopped for lunch yet? Someone.\""},
        {"pip", "Eat a bun, Noelle. Buns solve most things. A reindeer solves the rest, and he'd only need a stable."},
        {"agnes", "Sit, love. There's buns. And if the corner's sticky, that's my icing, so don't look at me."},
    }},
    {key="after-07", phase="after", level=7, replies={
        {index=2, building="reindeer_stable", line={"pip", "Agnes, I shut the stable latch! Mr Strand wants to know if your big oven's still cold!"}},
    }, lines={
        {"noelle", "Agnes, gingerbread gables with piped icing! Did you really do them all on the kitchen stove?"},
        {"pip", "Agnes, Mr Strand asks if your big oven's still cold! Not that he cares! He didn't say that!"},
        {"agnes", "Tell that man it's none of his business. And leave a bun on the back of the tray. Just in case."},
    }},
    {key="after-08", phase="after", level=8, lines={
        {"noelle", "Mr Strand! Your soldiers all face the coal yard. Why not the square?"},
        {"henrik", "Henrik Strand, toymaker. Best light. The square side is a plain wall, and I like a wall."},
        {"henrik", "Take the nutcrackers for the market, Noelle. They stand guard better than I do."},
    }},
    {key="after-09", phase="after", level=9, lines={
        {"noelle", "One cocoa, two spoons and a single marshmallow. Fair shares, Pip?"},
        {"pip", "My mum cooks on the coastal steamer. Her last postcard had a whale on it. It was a rock."},
        {"pip", "She sends one from every port. Want to see? They're in my satchel, next to the post."},
    }},
    {key="after-10", phase="after", level=10, lines={
        {"theo", "Paper stars in every window, and you still haven't put that parcel down. What's in it?"},
        {"noelle", "Gran's. \"For whoever needs it most.\" I'm gone on the 26th, Theo, so don't get used to me."},
        {"theo", "The twenty-sixth. Hm. The stars stay up till Twelfth Night, you know."},
    }},
    {key="after-11", phase="after", level=11, lines={
        {"noelle", "Twenty logs for the workshop, Theo, for one loaf and my sincere thanks. Final offer."},
        {"theo", "Twenty logs for a mulled wine every morning, with the cloves. That's mine."},
        {"noelle", "Deal! Fetch Pip for me, Theo. The reindeer settles down when he hears Pip's voice."},
    }},
    {key="after-12", phase="after", level=12, lines={
        {"noelle", "Hot chestnuts, Theo? Are they for sale? A stranger's note told me to stop for lunch, so I did."},
        {"theo", "Customers only. Since the timber, that's you. Take two. Mind your fingers. Who sent the note?"},
        {"noelle", "Don't ask who, Theo. That's the rule of the box. Honestly, you'd think you'd never heard of it."},
    }},
    {key="after-13", phase="after", level=13, lines={
        {"pip", "Noelle, shut your eyes and listen! Hear our reindeer's bells?"},
        {"noelle", "Jingle, jingle! Pip, every child in the lane has run out in one boot!"},
        {"theo", "Pip, find your other boot. Our reindeer thinks the bells are about him. He's not wrong."},
    }},
    {key="after-14", phase="after", level=14, lines={
        {"noelle", "Pip, a note! \"The carollers never agree on a key, but they wait for the slowest singer. Someone.\""},
        {"agnes", "That'll be me, love. Good King Wenceslas in three keys at once. Lovely."},
        {"wren", "Noelle, listen for the silver bell on the arch. It rings for the last one off the train."},
    }},
    {key="after-15", phase="after", level=15, lines={
        {"agnes", "Noelle, this was Rosa's sugar house. Candy chimney, gumdrop windows. Not one crumb for the goat."},
        {"noelle", "Agnes, it's perfect! And there's a goat on your roof. In tinsel."},
        {"agnes", "BRAMBLE! Get off my chimney, you wretched fluff!", story.SHOUT},
    }},
    {key="after-16", phase="after", level=16, lines={
        {"noelle", "Pip, there's a mitten with three thumbs on the line. Who's it for?"},
        {"pip", "Nobody! Practice! Can we have a firework stall, Noelle? Indigo rockets, in threes, for New Year!"},
        {"agnes", "Rockets go off outdoors, Pip. In a field, with a bucket of snow."},
    }},
    {key="after-17", phase="after", level=17, lines={
        {"noelle", "Agnes, hang a candy cane on every post and tell me. What really happened with Mr Strand?"},
        {"agnes", "Burnt bread, love. Something like that. Pass me the peppermints."},
        {"noelle", "Nobody sulks forty years over bread, Agnes. And you keep leaving him a bun."},
    }},
    {key="after-18", phase="after", level=18, replies={
        {index=3, building="firework_stall", line={"agnes", "Pip, feel in my apron. That's the rocket key. I need you here at New Year, whatever the sea does."}},
    }, lines={
        {"noelle", "Pip, skate all you like on the trough. Is your mum's steamer due before Christmas?"},
        {"pip", "It docks at Christmas, if the sea's kind. I don't mind if she can't come."},
        {"agnes", "Course you don't, pet. Have a bun."},
    }},
    {key="after-19", phase="after", level=19, lines={
        {"pip", "Noelle, Bramble ate his carrot, so Mrs Holt gave him a bun for a nose! Look in his scarf!"},
        {"noelle", "A note! \"You wrote you're only here till Christmas. Stay for the cocoa. Someone.\""},
        {"noelle", "Pip, nobody's ever asked me to stay for the cocoa. Why am I smiling?"},
    }},
    {key="before-20", phase="before", level=20, lines={
        {"pip", "Mrs Holt, Mr Strand's lent us his tall ladder for the fir! He says it's a loan!"},
        {"agnes", "He'll get it back polished, Pip. Now, who's holding the matches?"},
        {"noelle", "I am. Gran's matches, Agnes. Hold the ladder, everyone, and I'll light the first candle."},
    }},
    {key="after-20", phase="after", level=20, lines={
        {"pip", "NOELLE, MRS HOLT, LOOK UP! YOU CAN SEE THE WHOLE FIR! EVEN MR STRAND CAME OUT TO LOOK!", story.SHOUT},
        {"agnes", "Noelle, I'd forgotten it could look like this. Rosa lit the first candle every year."},
        {"noelle", "Three more Sundays, Agnes, three more candles. Will the wreath be full by Christmas?"},
    }},
    {key="before-21", phase="before", level=21, lines={
        {"agnes", "Gingerbread men in every window by Sunday, Noelle, and my oven back. That's all I ask."},
        {"pip", "Mrs Holt, is the oven back yet? Mr Strand says he doesn't care! He asked three times!", story.SHOUT},
        {"noelle", "You'll have your oven by Sunday, Agnes. Watch me."},
    }},
    {key="after-21", phase="after", level=21, lines={
        {"noelle", "Agnes, your oven's been cold since Gran went to the coast. Will you light it for me?"},
        {"pip", "Mrs Holt, will you take Mr Strand's penny? He says he doesn't want a bun! He said it twice!"},
        {"agnes", "Tell that man it's under a cloth on the back of the tray. Which he doesn't want."},
    }},
    {key="after-22", phase="after", level=22, lines={
        {"theo", "My stocking's a sock on a nail, with a pine cone in the toe. Every year. Tradition."},
        {"agnes", "Not this year, Theo. Rosa's old stockings are in my loft, and one's yours. Pip, fetch it."},
        {"pip", "Theo, it's got a sugar mouse in the toe! Why have you gone all quiet?"},
    }},
    {key="after-23", phase="after", level=23, lines={
        {"agnes", "Noelle, there was a crib in the chapel window. Since the roof went, it's lived in my loft."},
        {"pip", "Agnes, where's the donkey? The ox is here, and the angel's only got half a wing!"},
        {"noelle", "Then the chapel needs a roof, Agnes, and the crib goes back in its window. Gran would insist."},
    }},
    {key="after-24", phase="after", level=24, lines={
        {"noelle", "Pip, a note on my lantern pair! \"One lantern is a signpost. Two is a welcome. Someone.\""},
        {"pip", "It's a bit sticky at the corner. I only carry them! I'm just a satchel!"},
        {"noelle", "Sticky again, Pip. Gingerbread, or jam. I'm drawing up a list of suspects. Start talking."},
    }},
    {key="after-25", phase="after", level=25, lines={
        {"pip", "Mrs Holt, can I have one indigo rocket from the firework stall? Just one?"},
        {"agnes", "Those are for New Year, outdoors, in threes. Indoors you pull a paper cracker and wear the crown."},
        {"noelle", "New Year's after my train, Agnes. Funny how that stings more than it did."},
    }},
    {key="after-26", phase="after", level=26, lines={
        {"noelle", "Henrik, will you mend the crib's angel? Her wing's split. Bramble's been the donkey meanwhile."},
        {"henrik", "That angel is mine. I carved her years ago. The wing has split along the grain. Leave her with me."},
        {"agnes", "Noelle, I want her wing mended and the chapel roofed by Sunday. Nobody's thanking anybody."},
    }},
    {key="after-27", phase="after", level=27, replies={
        {index=3, building="chapel", line={"wren", "Leave your shoe by the chapel door tonight, Noelle. Someone may know your size."}},
    }, lines={
        {"pip", "Noelle! St Nicholas came! There's an orange and a chocolate coin in my shoe!"},
        {"noelle", "Mine's stuffed with cloves, Pip, and Agnes swears she slept all night. Who's doing it?"},
        {"wren", "Leave your shoe out again tonight, Noelle. A shoe by the door is a question. Someone answers."},
    }},
    {key="after-28", phase="after", level=28, lines={
        {"theo", "Forty wreaths, all plain pine, Noelle. Tasteful. Don't touch them."},
        {"noelle", "They look like hedges, Theo! Give me red ribbons, and a bow the size of Pip's head."},
        {"theo", "Fine. Red. But I'm telling everyone it was my idea."},
    }},
    {key="after-29", phase="after", level=29, lines={
        {"pip", "A TIN FROM MUM! Shortbread, a ship on the lid, and \"eat one for me.\" I've had four!", story.SHOUT},
        {"agnes", "Shortbread from the sea! Pass the tin, pet, I'm owed one of those four."},
        {"noelle", "Here's mine for the box, Pip. \"Dear anyone. Is it silly to like a place you're only visiting?\""},
    }},
    {key="after-30", phase="after", level=30, lines={
        {"pip", "Mrs Holt, did you see my calendar door? A tiny wooden hedgehog! Mr Strand carves them!"},
        {"agnes", "Tell that man it's the best hedgehog he's ever made."},
        {"henrik", "Pip, it is a badger. Tell that woman it has always been a badger."},
    }},
    {key="after-31", phase="after", level=31, lines={
        {"noelle", "First cup's yours, Mrs Alder. Will you take Gran's parcel, \"for whoever needs it most\"?"},
        {"alder", "Not me, dear. Give it to someone who'll open it on the day. Pour a second cup \"for whoever's next.\""},
        {"noelle", "For whoever's next. Then I'll stand the chipped robin mug on the counter, full, and wait."},
    }},
    {key="after-32", phase="after", level=32, lines={
        {"pip", "Mrs Holt, Mr Strand's mended the angel's wing, and he won't take a penny! What do I tell him?"},
        {"agnes", "Tell that man there's a honey cake on the back of the tray. It's for the mice."},
        {"henrik", "Tell that woman I haven't any mice. Tell her I'll take the cake regardless."},
    }},
    {key="after-33", phase="after", level=33, lines={
        {"pip", "Mrs Holt, can the Fenwick choir come in? Their hall roof leaks and their hymn books are soggy!"},
        {"agnes", "Soggy hymn books won't do. They'll practise in the chapel. I'll send biscuits."},
        {"alder", "Pour them the cup I paid for, Noelle. It's what it was for. And put me down for alto."},
    }},
    {key="after-34", phase="after", level=34, lines={
        {"theo", "Noelle, the lake froze overnight. I've drawn an ice house on the back of a bill. Very reasonable."},
        {"noelle", "A whole lake to build with, Theo! Is there ice left over for a rink?"},
        {"pip", "A rink! Mrs Holt skated here once, and Mr Strand too! I'm not supposed to say!"},
    }},
    {key="after-35", phase="after", level=35, lines={
        {"noelle", "Pip, I asked if it's silly to like a place I'm visiting. \"It isn't. It happens to people who look.\""},
        {"noelle", "There's a thumbprint on the corner, very sticky. Pip, I've decided Someone makes jam."},
        {"pip", "It could be anyone! It could be Mr Finch! It could be Bramble!"},
    }},
    {key="after-36", phase="after", level=36, lines={
        {"pip", "Mrs Holt, Mr Strand says your gingerbread men have no knees! He measured one with his ruler!"},
        {"agnes", "They aren't for walking, Pip. They're for eating. Noelle, will Theo's ice house keep my butter cold?"},
        {"noelle", "Till June, Agnes. And Bramble's eaten three knee-less men. She's back for a fourth."},
    }},
    {key="after-37", phase="after", level=37, lines={
        {"noelle", "Listen, Theo! The Fenwick choir's in the chapel, up to the second verse of \"The Holly and the Ivy.\""},
        {"theo", "They've sung it flat for thirty years. I'd leave it. Flat is a tradition."},
        {"alder", "Flat, Theo Marsh? My grandchildren say I'm the alto line now. We sing in the square. Be there."},
    }},
    {key="after-38", phase="after", level=38, replies={
        {index=2, building="igloo", line={"agnes", "Fetch the butter from Theo's shelf, Pip. I'll give the next batch knees. Don't tell him I smiled."}},
    }, lines={
        {"pip", "Mrs Holt, will you take a gingerbread cutter with knees? Mr Strand says it's a correction!"},
        {"agnes", "The next batch has knees, Pip. And thank you, said quietly, so he can't be sure."},
        {"noelle", "Agnes, I've been using my ticket as a bookmark in Gran's recipe book. It looks happier there."},
    }},
    {key="after-39", phase="after", level=39, lines={
        {"noelle", "Pip, listen. \"Sunday, in the square, I'll be the one not looking at the choir. Someone.\""},
        {"pip", "I carried it inside my hat all day! It's still warm! I mean. Hats are warm."},
        {"noelle", "Then I'll watch whoever isn't watching the choir. Pip, why are you turning pink?"},
    }},
    {key="before-40", phase="before", level=40, lines={
        {"agnes", "Second Sunday, second candle. Mrs Alder's lighting this one. She's earned it, love."},
        {"alder", "Noelle, steady the taper for me. I've sung flat for forty years. Tonight I mean to do it in public."},
        {"henrik", "Noelle, I can hear perfectly well from here, thank you."},
    }},
    {key="after-40", phase="after", level=40, lines={
        {"agnes", "Hush, the lot of you. It's \"Silent Night.\" Even the goat's listening."},
        {"pip", "MRS ALDER, YOU'RE UP! LIGHT THE SECOND CANDLE! THE WHOLE CHOIR'S WAITING FOR YOU!", story.SHOUT},
        {"alder", "Flat as a pancake and nobody minded! Noelle, you've icing on your chin. And Theo's been staring."},
    }},
    {key="before-41", phase="before", level=41, lines={
        {"pip", "Noelle, the choir sang till the icicles rang, and now I'm hoarse! What's the next candle for?"},
        {"agnes", "Rose-pink, love. Third Sunday, \"rejoice\". It's the only cheerful one."},
        {"noelle", "Agnes, Gran's parcel is still in my mittens, and I still don't know who needs it most. Any ideas?"},
    }},
    {key="after-41", phase="after", level=41, lines={
        {"theo", "Planks for the smokehouse, Mr Finch? Dry ones. And smell that, Noelle. Fir boughs for every door."},
        {"finch", "No knots, Theo. My trout want a tight smokehouse. I stand outside every service, holding Bramble."},
        {"noelle", "Every service, Mr Finch? Can't Bramble wait by herself? She's only a goat."},
    }},
    {key="after-42", phase="after", level=42, replies={
        {index=2, building="log_cabin", line={"agnes", "By the stove, love. Mr Finch took the applewood, so there's room for Rosa's whole string."}},
    }, lines={
        {"noelle", "Agnes, where do these Christmas cards go? Is this one from 1983?"},
        {"agnes", "On the string by the stove, love. I've kept every one since Rosa started sending hers."},
        {"pip", "Agnes, there's one from Mr Strand, no stamp, under the door! Where do I pin it?"},
    }},
    {key="after-43", phase="after", level=43, lines={
        {"theo", "Noelle, hold a block of ice up to a lantern. The cutters brought it off the lake. Clear as glass."},
        {"noelle", "Pip, look! The whole lane's in there, upside down!"},
        {"pip", "Come and get chestnut soup, Noelle! The cutters are singing O Christmas Tree with their mouths full!"},
    }},
    {key="after-44", phase="after", level=44, lines={
        {"pip", "Mrs Holt, Mr Strand says your gingerbread bows have five loops. A bow wants two and a tail."},
        {"agnes", "Bun bows, not bridges. Five loops. Pass the scissors, Pip."},
        {"henrik", "Pip, take her this spool of narrow ribbon. Free. For the sake of the buns."},
    }},
    {key="after-45", phase="after", level=45, lines={
        {"noelle", "Pip, frost ferns on every window, and you've gone a bit green. Are you well?"},
        {"pip", "I know who Someone is. I know, and I can't say. Look at the frost, Pip. Look at the frost.", story.THOUGHT},
        {"pip", "I'M FINE! THE RULE IS THE RULE! I'M GOING TO SHOUT INTO A SACK!", story.SHOUT},
    }},
    {key="after-46", phase="after", level=46, lines={
        {"pip", "Noelle, Otis will bring a clock if we open the kiosk. Could I wind it? I'd see every train!"},
        {"noelle", "Watching for your mum? You said you didn't mind."},
        {"pip", "I don't! I just check. Sometimes. Every train. Have a gingerbread man."},
    }},
    {key="after-47", phase="after", level=47, lines={
        {"noelle", "Agnes, one stocking has no name on it, and there's a bun inside. Who's it for?"},
        {"agnes", "Whoever comes in from the cold, love. Not a word. Eat your satsuma."},
        {"finch", "Mrs Holt, may I hang one for Bramble? Carrot in the toe. She can't be left, or I'd be in chapel."},
    }},
    {key="after-48", phase="after", level=48, replies={
        {index=1, building="station_kiosk", line={"pip", "Mrs Holt, I saw the candle girl from my kiosk. Have you a saffron bun for her walk?"}},
    }, lines={
        {"pip", "Mrs Holt, may the choir girl in the candle crown have saffron buns? She's walking the whole lane!"},
        {"agnes", "Saffron buns for her, pet. And we've borrowed every candle in town, so nobody blow one out."},
        {"noelle", "Agnes, the wax is still warm on my sleeve. We'll need a proper candle shop before next year."},
    }},
    {key="after-49", phase="after", level=49, lines={
        {"noelle", "Agnes, oranges stuck with cloves all along your window! The lane smells like Christmas morning."},
        {"pip", "Mrs Holt, Mr Strand sent his penny again, for a fourth bun he doesn't want! Into the jar?"},
        {"agnes", "Into the jar, Pip. It's nearly full. Then I'll have something to say."},
    }},
    {key="after-50", phase="after", level=50, lines={
        {"finch", "Noelle, the crib's lit again. I'll stand outside with Bramble, as always. She likes the carols."},
        {"wren", "She'll do. You're one shepherd short, though. Don't fret. They turn up late and out of breath."},
        {"noelle", "Then we'll leave a space by the ox, Mr Wren. Mr Wren? Gone. Mr Finch, did you see him go?"},
    }},
    {key="after-51", phase="after", level=51, lines={
        {"henrik", "Noelle, stand at the window and tell me honestly. Is the glass true? Mind the putty."},
        {"noelle", "Perfectly true, Henrik. And it looks straight at the bakery. Was that on purpose?"},
        {"henrik", "Does it? Hadn't noticed. Thirty-one paces, door to door. Not that I've counted."},
    }},
    {key="after-52", phase="after", level=52, lines={
        {"henrik", "Pip, take this across: my nutcrackers are guarding her bakery. Somebody ought to."},
        {"agnes", "Pip, they're frightening my customers. And the king's crooked."},
        {"pip", "I'm standing in the middle! You're both right there! Fine! I'll go and straighten the king!"},
    }},
    {key="after-53", phase="after", level=53, lines={
        {"theo", "Noelle, Mr Finch wants a word at the smokehouse. First trout's done, and he's gone shy."},
        {"finch", "Forty Christmases I've stood outside the chapel holding a goat. Know a goat-minder?"},
        {"noelle", "Not yet, Mr Finch. But I'll find one before Christmas Eve. Save me a trout."},
    }},
    {key="after-54", phase="after", level=54, lines={
        {"noelle", "Pip, look: \"What carol do you hum when nobody's listening?\" Mr Finch, is this yours?"},
        {"finch", "I smoke fish, Noelle. Jam's not my line. I do hum Wenceslas. Badly."},
        {"pip", "I AM A VAULT! A VAULT WITH CIDER! ASK ME NOTHING!", story.SHOUT},
    }},
    {key="after-55", phase="after", level=55, lines={
        {"alder", "Hold the end of the star string, Noelle. Sixty stars, all mine. Now, who's your Someone?"},
        {"noelle", "Mrs Alder! The rule is never ask. Who's on your list?"},
        {"alder", "Three names, and I'm not saying. Never ask is for you, dear. I'm only guessing."},
    }},
    {key="after-56", phase="after", level=56, lines={
        {"pip", "Noelle, hold the lantern! The red scarf's for my mum. The blue one was my first try. Three arms."},
        {"noelle", "Pip, would you like Gran's parcel? \"For whoever needs it most.\" I think it might be you."},
        {"pip", "Keep it. I said I don't mind about Mum. I mind. A bit. Quite a lot, actually."},
    }},
    {key="after-57", phase="after", level=57, lines={
        {"alder", "Noelle, my grandchildren painted every star on that box. Tell them the gold's straight."},
        {"pip", "Noelle, leave the old green box alone, will you? Its lining's loose. It ate my mitten once."},
        {"noelle", "Santa gets the red one, the green one gets a talking-to. Pip, I'm writing back tonight."},
    }},
    {key="after-58", phase="after", level=58, lines={
        {"noelle", "Pip, wait! My note: \"The lane was lovely tonight. I may have sung. Noelle.\" I SIGNED it!"},
        {"noelle", "Give it back, Pip, please. You can't deliver it with my name on it."},
        {"pip", "TOO LATE, IT'S IN THE BOX! I DID NOT SEE YOUR NAME! THE RULE IS THE RULE! BYE!", story.SHOUT},
    }},
    {key="after-59", phase="after", level=59, lines={
        {"pip", "Agnes, Mr Strand sent a table cracker across! A paper crown and a joke inside!"},
        {"agnes", "\"A snowman in summer? A puddle.\" Henrik Strand, that's dreadful. I'm laughing. Don't tell him."},
        {"noelle", "Agnes, you're laughing! And I signed my note by mistake, so we've both had a week."},
    }},
    {key="before-60", phase="before", level=60, lines={
        {"agnes", "Third Sunday, the rose-pink candle, for rejoicing. Noelle, you light it. Long taper."},
        {"pip", "Theo, hold out your hand and don't look! Note from the box, folded small! I'm gone!"},
        {"theo", "Pip, you're running like a goat on ice. Gloves off, then."},
    }},
    {key="after-60", phase="after", level=60, lines={
        {"noelle", "Theo, you've gone pink as the candle. Are you well? Or is it another bill?"},
        {"theo", "\"I may have sung. Noelle.\" All these weeks I've been writing back to her. It was her all along.", story.THOUGHT},
        {"pip", "I SAW NOTHING! REJOICE! EVERYONE REJOICE! I AM REJOICING VERY QUIETLY!", story.SHOUT},
    }},
    {key="before-61", phase="before", level=61, lines={
        {"noelle", "Three candles lit, and Theo said good morning like he meant it. What's got into him?", story.THOUGHT},
        {"pip", "NOTHING'S GOT INTO HIM! I've got letters to run!", story.SHOUT},
        {"agnes", "When you bring the wrapping paper, have a look at the old green postbox for me, love."},
    }},
    {key="after-61", phase="after", level=61, lines={
        {"alder", "Hold my lantern, Noelle. Envelope behind that lining: H. Strand. Smells of Agnes's kitchen."},
        {"pip", "Henrik Strand! There's flour in the fold! Shall I run it over? A penny a message!"},
        {"noelle", "No, Pip. This one I'll carry myself. It's been waiting long enough."},
    }},
    {key="after-62", phase="after", level=62, lines={
        {"theo", "Hold the ladder, would you, Noelle? Mistletoe. Purely decorative. Nothing to read into it."},
        {"noelle", "You're standing nine feet from it, Theo. And I've a letter for Henrik. His door has a queue."},
        {"theo", "Spinning tops. Try him at lunch, when he eats alone. I'll hold the ladder and the queue."},
    }},
    {key="after-63", phase="after", level=63, replies={
        {index=3, building="station_kiosk", introduction="placed-station_kiosk", when="visit-station_kiosk-placed-station_kiosk.personal", line={"otis", "Leave his door shut, Pip. Here's the tin lid. Your brass buttons go first while he reads."}},
        {index=3, building="station_kiosk", introduction="placed-station_kiosk", line={"otis", "Leave the door shut, Pip. Come sit on the step with me. Mr Strand can tell us when he's ready."}},
    }, lines={
        {"noelle", "Mr Strand? This was stuck behind the postbox lining. It's very old. Please open it."},
        {"henrik", "That's Agnes Holt's writing. Every t crossed like a sword. I'll need my good spectacles."},
        {"pip", "Noelle, the clock's striking twelve and he's shut the door on us! What do we do?"},
    }},
    {key="after-64", phase="after", level=64, lines={
        {"henrik", "Noelle, \"Meet me by the big fir on Christmas Eve. A.\" Forty years ago. She waited, in the snow."},
        {"noelle", "Henrik, Agnes is shaping marzipan pears across the square, and not looking at your window. Hard."},
        {"henrik", "I thought it was my remark about her bread. I need a minute. And a better coat."},
    }},
    {key="after-65", phase="after", level=65, lines={
        {"pip", "HENRIK'S CROSSING THE SQUARE, AGNES! BEST COAT, TOY TRAIN, COMING YOUR WAY!", story.SHOUT},
        {"henrik", "I'm late, Agnes. I brought a train. I'd have brought the fir, but it's rooted."},
        {"agnes", "You daft old man. You're late. Come in, there's a bun."},
    }},
    {key="after-66", phase="after", level=66, lines={
        {"agnes", "Sit, Henrik. Eat. The jar's full, and the whole shop's heard about the fir and the forty years."},
        {"pip", "You told everyone? Mrs Alder cried into the dough! And nobody needs a messenger now. I'm unemployed!"},
        {"noelle", "Then run a post office, Pip! Every child will write to Santa, and you know every lane."},
    }},
    {key="after-67", phase="after", level=67, replies={
        {index=2, building="post_office", line={"pip", "I'm the postmaster, Agnes. Can I put an express stamp on my wish for Mum's steamer?"}},
    }, lines={
        {"agnes", "Stir once, east to west, and wish. Rosa sent her recipe from the coast: \"less brandy.\""},
        {"pip", "I wished for a fast steamer! That's all I'm saying!"},
        {"noelle", "Gran writes you a recipe and me a parcel, Agnes. What is she up to?"},
    }},
    {key="after-68", phase="after", level=68, lines={
        {"pip", "Mr Strand! Mrs Holt! The sleigh's going round under the first stars. Shall I steer?"},
        {"henrik", "Agnes, you said I was holding the reins wrong."},
        {"agnes", "You were. I've kept the blanket, mind."},
    }},
    {key="after-69", phase="after", level=69, lines={
        {"noelle", "Pip says there's a shed full of unpainted horses, Henrik. Why?"},
        {"henrik", "Twelve of them. I carve when I'm cross. I've been cross a long while."},
        {"pip", "Twelve horses, twelve families! Noelle, it's a carousel! I want the one with the ears!"},
    }},
    {key="after-70", phase="after", level=70, lines={
        {"pip", "Henrik, twelve horses and we've three tins of paint and one old sock! Who gets which?"},
        {"wren", "Give the third horse to the family with most to say. It leans a touch to the left."},
        {"henrik", "That's the first one I carved. How did you know, Wren? I was very cross that week."},
    }},
    {key="after-71", phase="after", level=71, lines={
        {"pip", "Agnes, Ada Pike wrote from across the lake. She'll bring her blowing irons if we find a furnace!"},
        {"agnes", "Yes, if she blows me a dome for the gingerbread. Noelle, why are you staring at your ticket?"},
        {"noelle", "It's gone soft at the corners, Agnes. I hadn't looked at it in days."},
    }},
    {key="after-72", phase="after", level=72, lines={
        {"theo", "Pip, come shake the harness bells for me. Dobbin needs a bell boy. Pay's in cocoa."},
        {"pip", "I'm the bell boy! Noelle, listen, he's keeping step with me!"},
        {"noelle", "Then you'll need a hat, Pip. Henrik's sewing felt ones for the sleigh."},
    }},
    {key="after-73", phase="after", level=73, lines={
        {"noelle", "Pip, a note on my window: \"Look at it before the sun does. Someone.\" Who stands out at dawn?"},
        {"pip", "Why are you looking at me? It smells a bit of pine, which is nothing! Pine's everywhere!"},
        {"noelle", "It's December, Pip. Come on, before the sun gets the bakery window."},
    }},
    {key="after-74", phase="after", level=74, replies={
        {index=3, building="glassblower", introduction="placed-glassblower", line={"ada", "She'll wash, Mr Finch. Noelle, try my dome. I left room for snow on the gingerbread roof."}},
    }, lines={
        {"noelle", "Mr Finch, hold the ladder! The Fenwick choir brought paint, and why is Bramble blue?"},
        {"finch", "She helped. Chapel won't have a blue goat. Still no goat-minder, Noelle?"},
        {"agnes", "She'll wash. Look at that! Henrik's piped every window of my ginger cottage dead level. Show-off."},
    }},
    {key="after-75", phase="after", level=75, lines={
        {"agnes", "Two stockings on the bakery mantel this year, Pip. Don't look at me like that."},
        {"pip", "Agnes, the second one says H! In marzipan!"},
        {"henrik", "The H leans. I shall never correct it."},
    }},
    {key="after-76", phase="after", level=76, lines={
        {"noelle", "Henrik, twelve horses and a reindeer! I'm not crying, it's the cold. Who rides first?"},
        {"henrik", "Agnes, first ride. You're on the third horse. It leans to the left, and so do I."},
        {"noelle", "Agnes, I'd like to see these horses in January. Snow on their backs, nobody hurrying."},
    }},
    {key="after-77", phase="after", level=77, lines={
        {"pip", "Noelle, the post office queue's out the door! I stamp every envelope with a wish cross. Official!"},
        {"alder", "Stamp mine twice, Pip. Four grandchildren have asked Santa for a goat. Blame Bramble."},
        {"noelle", "Then Santa needs a bigger sack. I'm writing to him too, Pip. Don't look."},
    }},
    {key="after-78", phase="after", level=78, lines={
        {"pip", "Noelle, Bramble's on the pond in tinsel! She's going backwards!"},
        {"theo", "The ice house says six inches thick. Bramble says twelve. I trust the goat."},
        {"noelle", "Do you skate, Theo? I fall over with great style."},
    }},
    {key="after-79", phase="after", level=79, lines={
        {"pip", "Noelle, a note came through the frozen fountain! I did not read it!"},
        {"noelle", "\"Meet me by the big fir on Christmas Eve. Someone.\" Pip, those are Agnes's words, exactly!"},
        {"noelle", "The whole bakery heard her tell that story. Someone's borrowed Agnes's words. I'll be there."},
    }},
    {key="before-80", phase="before", level=80, lines={
        {"noelle", "Three candles burning, and one still dark. Who lights it, Agnes?"},
        {"agnes", "Not me alone, love. I've held a taper by myself long enough."},
        {"henrik", "Then I'll hold the other end. Mind my sleeve."},
    }},
    {key="after-80", phase="after", level=80, lines={
        {"pip", "NOELLE, DID YOU SEE? ONE TAPER, FOUR HANDS! EVEN BRAMBLE'S STOPPED CHEWING!", story.SHOUT},
        {"henrik", "Agnes, straight as a plumb line. Not a drop of wax on my sleeve."},
        {"noelle", "Agnes, Christmas Eve is coming up the lane, and I've an appointment by the fir. What do I wear?"},
    }},
    {key="before-81", phase="before", level=81, lines={
        {"pip", "NOELLE! FOUR CANDLES! ONLY THE STAR LEFT! HELP! I'VE LACED MY SKATES ON THE WRONG FEET!", story.SHOUT},
        {"noelle", "Swap them, Pip. Agnes, ticket in one mitten, \"Meet me by the fir\" in the other. Which wins?"},
        {"agnes", "Skates on, the lot of you. I haven't skated in forty years. Don't stare."},
    }},
    {key="after-81", phase="after", level=81, lines={
        {"pip", "Noelle, catch me! Everyone's on the ice and half of them are lying down!"},
        {"agnes", "Eyes front, Henrik. You're on my foot."},
        {"henrik", "I'm forty years late, Agnes. I'm allowed one foot."},
    }},
    {key="after-82", phase="after", level=82, lines={
        {"pip", "Noelle, I've sung Hark! The herald angels nine times while Mrs Holt skated. Also, a note for you!"},
        {"noelle", "\"Wear something warm. The fir is draughty. Someone.\" Someone worries about my toes, Pip!"},
        {"agnes", "Thick mittens, love. That fir has a full diary. Mine was only forty years overdue."},
    }},
    {key="after-83", phase="after", level=83, lines={
        {"noelle", "Agnes, a red ribbon with my name on it in six-year-old writing! Where did it come from?"},
        {"agnes", "Rosa's biscuit tin, under a stack of old Christmas cards. A nutcracker sat on the lid."},
        {"noelle", "\"I wish everyone could stay.\" Agnes, she kept it all these years and never said. Did you know?"},
    }},
    {key="after-84", phase="after", level=84, replies={
        {index=1, building="glassblower", introduction="placed-glassblower", line={"ada", "Henrik, steady the ladder. Noelle, tie Gran's ribbon on my glass bell. I blew it for her."}},
    }, lines={
        {"noelle", "Henrik, there's an amber bauble in Gran's tin. Will you help me tie her ribbon on?"},
        {"henrik", "Hang it lower, Noelle. A child's eye is three feet off the ground, not six."},
        {"noelle", "Low it is. Red ribbon, amber glass, one wish. Hold the ladder, Henrik?"},
    }},
    {key="after-85", phase="after", level=85, recall={key="meeting-station_kiosk-glassblower.after-85", meeting="meeting-station_kiosk-glassblower", exchanges={
        ["neither"]={
            {"ada", "Pip needs a game while he waits for his mum. May we borrow your tin lid, Mr Bell?"},
            {"otis", "If you'll play him, Miss Pike. You took the last two buttons off me in our first game."},
        },
        ["glassblower"]={
            {"ada", "Pip wants to hear those two pings I got when I beat you. Will you lend him your lid, Mr Bell?"},
            {"otis", "Gladly. I'll sit by the kettle. That lid rings louder when you're losing."},
        },
        ["station_kiosk"]={
            {"otis", "Shall we teach Pip that double jump, Miss Pike? I'll leave two men out for him like I did for you."},
            {"ada", "Oh, you play on Pip's side this time, Mr Bell. Let's see if you can keep those last two buttons."},
        },
        ["both"]={
            {"ada", "Pip's lined up two buttons for me, Mr Bell. Have you been giving him lessons?"},
            {"otis", "Give him a practice game, Miss Pike. He wants his mum to hear two pings when her train gets in."},
        },
    }, lines={
        {"otis", "Miss Pike, may I have my tin lid back? You and Pip have finished your game and my pie's gone cold."},
        {"ada", "Here you are, Mr Bell. I've put the buttons in your pocket. Mind you don't bake them in tomorrow."},
    }, followups={
        {key="meeting-station_kiosk-glassblower.after-85.glassblower", building="glassblower", when="meeting-station_kiosk-glassblower.after-85", topic="recall", label="How did Pip do against you?", lines={
            {"noelle", "Ada, who won when you played Pip on Mr Bell's lid?"},
            {"ada", "Pip did. I jumped the two buttons he left me. He jumped my blue one straight into his mitten."},
        }, replies={
            {index=1, building="station_kiosk", when="meeting-station_kiosk-glassblower.after-85.station_kiosk", line={"noelle", "Mr Bell says Pip hushed him. Did you see the winning jump coming, Ada?"}},
            {index=2, building="station_kiosk", when="meeting-station_kiosk-glassblower.after-85.station_kiosk", line={"ada", "I saw two easy buttons, Noelle. Pip saw my blue one landing in his mitten. He won it fair."}},
        }},
        {key="meeting-station_kiosk-glassblower.after-85.station_kiosk", building="station_kiosk", when="meeting-station_kiosk-glassblower.after-85", topic="recall", label="Did Pip need any coaching?", lines={
            {"noelle", "Did you have to whisper the moves to Pip, Mr Bell?"},
            {"otis", "I took a breath. Pip put a finger to his lips and won all by himself. I drank my tea."},
        }, replies={
            {index=1, building="glassblower", when="meeting-station_kiosk-glassblower.after-85.glassblower", line={"noelle", "Ada says Pip caught her blue button in his mitten. Whose idea was that, Mr Bell?"}},
            {index=2, building="glassblower", when="meeting-station_kiosk-glassblower.after-85.glassblower", line={"otis", "Pip's. I opened my mouth and he put a finger to his lips. First match I've coached by drinking tea."}},
        }},
    }}, lines={
        {"pip", "A TELEGRAM! \"ON LAST TRAIN CHRISTMAS EVE. SAVE ME A PRETZEL. MUM.\" SHE'S COMING, NOELLE!", story.SHOUT},
        {"noelle", "Then the station path gets a lantern on every post, and a bun at the end. Agnes?"},
        {"agnes", "Pip, keep that kiosk clock right. I'll have the bun in her hand before the steam's off the engine."},
    }},
    {key="after-86", phase="after", level=86, lines={
        {"agnes", "Noelle, it's the shortest day and dark by four. Take a box of jam jars. Every sill gets a candle."},
        {"noelle", "Agnes, nobody leaves without cocoa, and I'll light every window myself."},
        {"henrik", "My old apprentices would come back for a proper hall, Noelle. A carved reindeer for every child."},
    }},
    {key="after-87", phase="after", level=87, lines={
        {"noelle", "Agnes, the glass turned my ticket red and gold. The twenty-sixth looks very small tonight."},
        {"agnes", "You've held that ticket through three carols, love. Come and hold a mug instead."},
        {"noelle", "Agnes, what's Bellmere like in January? Snow on the horses, nobody hurrying? I think I'd like that."},
    }},
    {key="after-88", phase="after", level=88, replies={
        {index=1, building="santa_workshop", line={"noelle", "Theo, thank you for the lantern hooks. Even Pip made one for his bench at the hall."}},
    }, lines={
        {"noelle", "Theo, thank you for the good hooks, and for carrying the lanterns. Needles and all."},
        {"theo", "They'll hang till Twelfth Night, Noelle. Someone should be here in January to take them down."},
        {"noelle", "January, Theo? You said it as though it were nothing. It's the nicest thing anyone's said to me."},
    }},
    {key="after-89", phase="after", level=89, replies={
        {index=2, building="glassblower", introduction="placed-glassblower", line={"ada", "Noelle, the whole town brought lamps. Take mine for the bend. I blew a chimney for this wind."}},
    }, lines={
        {"noelle", "Agnes, the wind's blown out every lamp on the station path! I can't even see the bend!"},
        {"agnes", "Turn round, love. The whole town's brought a lamp, and Fenwick lent one for the bend."},
        {"noelle", "Thank you, all of you! Now come on. Let's light it for the last train on Christmas Eve."},
    }},
    {key="after-90", phase="after", level=90, replies={
        {index=3, building="glassblower", introduction="placed-glassblower", when="visit-glassblower-after-84.personal", line={"ada", "Noelle, I brought my spoons. Give me that nod we talked about and I'll play for the choir."}},
        {index=3, building="glassblower", introduction="placed-glassblower", line={"ada", "Noelle, lend me two teaspoons when you've poured. Those singers could use someone to keep time."}},
    }, lines={
        {"pip", "Agnes, the Fenwick choir's in the loft, and their socks are drying on your stove! Can they stay?"},
        {"agnes", "Their roof can wait. Tea first, carols second. Mrs Alder, sing quietly."},
        {"alder", "A cup for each of them, Noelle, and I'm paying for one more by the stove."},
    }},
    {key="after-91", phase="after", level=91, lines={
        {"wren", "Every stall brought a lamp for the big fir, Noelle. When's your train?"},
        {"noelle", "Never. The ticket goes in the fir, with a lamp. Mr Wren, would you like Gran's parcel?"},
        {"wren", "Open it yourself, Noelle. And mind the third step. It's a sly one."},
    }},
    {key="after-92", phase="after", level=92, lines={
        {"noelle", "Henrik, Gran's parcel was her front-door key! The lock sticks and the third step creaks!"},
        {"henrik", "A nail's width proud. I'll plane it down before the new year."},
        {"noelle", "Don't. I've grown fond of it. Pass me the pine boughs. Her stairs should smell lovely."},
    }},
    {key="after-93", phase="after", level=93, lines={
        {"pip", "Noelle, a note! And a spiced star's cooling on the sill. Don't touch it!"},
        {"noelle", "\"I've saved you the one seat by the fir with no sap on it. Someone.\""},
        {"noelle", "Someone clearly doesn't work with trees, Pip. Tell me if you see anyone sit there."},
    }},
    {key="after-94", phase="after", level=94, lines={
        {"pip", "MUM! I KNITTED YOU A SCARF! IT'S TERRIBLE! PUT IT ON!", story.SHOUT},
        {"mary", "It's two sizes too long, and I love it. Wear one end, Pip. I'll wear the other."},
        {"rosa", "Last one off the train, Noelle, so the silver bell's for me. Did you think I'd miss it?"},
    }},
    {key="after-95", phase="after", level=95, lines={
        {"noelle", "Gran! Your old lamp was behind the jam jars. It's lit in your window, and I've got your key!"},
        {"rosa", "I wrote \"whoever needs it most\" because I didn't dare write your name. A light for one more."},
        {"alder", "Rosa, this cup's been paid for since the kiosk opened. For whoever's next. You're next."},
    }},
    {key="after-96", phase="after", level=96, lines={
        {"pip", "Mr Wren! A red sleigh with no tracks, and YOUR BROOM'S LEANING ON IT! Explain!", story.SHOUT},
        {"rosa", "Mr Wren, that sleigh wasn't here when I got off the train. Did you bring it? I'd like a ride."},
        {"wren", "I only brought the broom, Rosa. Sleighs turn up where there's a good reason. Mind the runners."},
    }},
    {key="after-97", phase="after", level=97, lines={
        {"noelle", "Pip, you're late and out of breath, exactly as Mr Wren said a shepherd would be. Stand by the ox."},
        {"agnes", "Solemn at the star, Pip. Wave once more and you're the ox."},
        {"finch", "Front pew, Noelle. First time in forty winters. Rosa's got the goat."},
    }},
    {key="after-98", phase="after", level=98, replies={
        {index=2, building="sleigh", line={"mary", "Pip, yours has your nose exactly. Come and sit by me in Rosa's sleigh."}},
    }, lines={
        {"henrik", "Pip, fourteen apprentices carved a reindeer for every child. Will you wrap them at the pavilion?"},
        {"mary", "Pip, yours has your nose exactly. Go and show Rosa. She's been asking for you."},
        {"henrik", "Last one's for you, Agnes. Now I'm off to wait under the fir. Early, for once."},
    }},
    {key="after-99", phase="after", level=99, lines={
        {"noelle", "Pip, where's Theo? He's been scarce all evening."},
        {"pip", "Busy! Trees! He's very busy with one tree! Noelle, the goat's got the bell rope, don't look up!"},
        {"alder", "Eleven chimes, Noelle. I've had my money on a tree-seller since August. Off you go."},
    }},
    {key="before-100", phase="before", level=100, lines={
        {"agnes", "Noelle, it's five to midnight, and there's a man under the fir pretending to look at a tree."},
        {"noelle", "Which man?"},
        {"agnes", "Go and find out, love. Some of us waited forty years."},
        {"rosa", "Go on, Noelle. I didn't send you to Bellmere to stand about. Mind the third step."},
    }},
    {key="after-100", phase="after", level=100, lines={
        {"noelle", "Theo! You're Someone! Resin on every note. You said it gets on your letters!"},
        {"theo", "I saw your name on the last one. Thought I'd answer this one in person."},
        {"noelle", "You've been polite to me all week. I thought you were ill."},
        {"noelle", "\"Stay for the cocoa,\" you wrote. Gran's lamp is in my window and I've her key. I'm staying."},
        {"pip", "SOMEONE SAID YES! EVERYBODY LOOK! I NEVER READ A SINGLE NOTE!", story.SHOUT},
    }},
    {key="upgrade-man_03", phase="upgrade", event="man_03", title="a mulled-wine hatch in the arch", building="Welcome arch", lines={
        {"noelle", "Theo, come and see! A hatch in the arch, so the mulled wine comes out through the wall!"},
        {"theo", "Wine through a wall. Fine, but who ladles it? Not me. My gloves are sticky."},
        {"noelle", "Nobody ladles. Just stand under it and tell everyone it was your idea. Cinnamon first?"},
    }},
    {key="upgrade-man_04", phase="upgrade", event="man_04", title="a new harness and bells for the reindeer", building="Reindeer stable", lines={
        {"pip", "Mr Wren, hold his harness! The bells are mine. I polished every one!"},
        {"wren", "Let him hear them first, Pip. He likes to know whose tune he's wearing."},
        {"pip", "He keeps lifting his feet like a cat in snow. Does that mean he likes them?"},
    }},
    {key="upgrade-man_02", phase="upgrade", event="man_02", title="a drying shed for the pine", building="Lumber workshop", lines={
        {"theo", "Noelle, don't touch the pine. It's drying. I built a shed. A whole shed, for planks."},
        {"noelle", "You, fussing over planks? Theo Marsh, that's sweet. Why a shed?"},
        {"theo", "Wet wood spits sparks and splits stalls, Noelle. And yes, it's a bit sweet. Tell nobody."},
    }},
    {key="upgrade-man_01", phase="upgrade", event="man_01", title="a rocket rack, ready in threes", building="Firework stall", lines={
        {"pip", "Mrs Holt, you should see the rockets! They stand in a rack now, in threes. Nothing rolls!"},
        {"agnes", "Rolls? Pip Larkin, what rolled? And where did it roll to?"},
        {"pip", "Nowhere! Bramble only sniffed one. Sniffed! Have a bun. No, you have the buns, sorry!"},
    }},
    {key="upgrade-man_05", phase="upgrade", event="man_05", title="a second oven", building="Gingerbread bakery", lines={
        {"agnes", "Don't gloat. Yes, there's a second oven. One batch bakes while the next one rises."},
        {"noelle", "Gloat? You've been grinning at it for an hour. Has it got a name yet?"},
        {"agnes", "It's an oven, love. The tall one's for gingerbread. The little one's for the hungry. Sit."},
    }},
    {key="upgrade-man_06", phase="upgrade", event="man_06", title="the masons' yard behind the chapel", building="Snowy chapel", lines={
        {"wren", "Pip, run and tell the masons the chapel step is wanted. Stone keeps its own hours."},
        {"pip", "A whole yard of masons? Where did they come from? Did you ask them, Mr Wren?"},
        {"wren", "I only mentioned the step. Mind the chisels, they're cold and they bite."},
    }},
    {key="upgrade-man_07", phase="upgrade", event="man_07", title="Mrs Alder's ladle and second pot", building="Hot cocoa kiosk", lines={
        {"alder", "Theo Marsh, taste this! Second pot, my own ladle. Nutmeg, and a little orange."},
        {"theo", "Not bad. Don't tell Agnes, or she'll want a pot of her own."},
        {"alder", "She can queue. Hold the cup and stand still while I hum you the carol it goes with."},
    }},
    {key="upgrade-man_08", phase="upgrade", event="man_08", title="a second ice saw on the lake", building="Ice house", lines={
        {"theo", "Mr Finch, that's the second ice saw. Twice the blocks, and nobody wet. Keep your goat off it?"},
        {"finch", "Bramble walked out on the ice this morning. It held. Your sawing's fine."},
        {"theo", "You let your goat test my ice? She could have gone through!"},
        {"finch", "She doesn't. She's very particular. Same as you."},
    }},
    {key="upgrade-man_09", phase="upgrade", event="man_09", title="a second smoking rack", building="Lakeside smokehouse", lines={
        {"alder", "Mr Finch, two racks! Will there be trout for the whole lane at Christmas?"},
        {"finch", "One rack for the trout. One for Bramble's share. She won't touch fish. I keep asking."},
        {"alder", "Then give her share to my grandchildren. They'll eat anything tied with a ribbon."},
    }},
    {key="upgrade-man_10", phase="upgrade", event="man_10", title="a second bench and a shop bell", building="Toymaker's workshop", lines={
        {"henrik", "Pip, don't slam it. It's a shop bell, not a drum. One ring per customer."},
        {"pip", "But it's so loud! Mr Strand, why do you need two benches? Is somebody coming to help?"},
        {"henrik", "A bench stays free in case someone wants to learn. The bell tells me they've come."},
    }},
    {key="upgrade-man_11", phase="upgrade", event="man_11", title="Mr Wren trims every wick", building="Candlelight shop", lines={
        {"wren", "Mind your sleeve, Noelle. A wick wants trimming to a sparrow's eyelash."},
        {"noelle", "Mr Wren, you've done every wick in the shop. When do you ever sleep?"},
        {"wren", "Wicks don't mind. Take one home for your window. Light likes to be seen."},
    }},
    {key="upgrade-man_12", phase="upgrade", event="man_12", title="a second sorting rack", building="North Pole post office", lines={
        {"pip", "Theo, I have my own rack now! Letters sorted by lane. The Kind Word box goes first!"},
        {"theo", "Do you read them? Look me in the eye, Pip."},
        {"pip", "I only read the envelopes! Mostly! Please don't tell Mr Wren I said mostly!"},
    }},
    {key="upgrade-man_13", phase="upgrade", event="man_13", title="a second furnace", building="Glassblower's stall", lines={
        {"theo", "Agnes, say it. Anything glass, any size. The second furnace is hungry."},
        {"agnes", "A dome for the gingerbread. Pip's thumbs go through everything on that counter."},
        {"theo", "Tall, so the gingerbread men can stand up straight. I'll have it before your next batch."},
        {"agnes", "No bubbles, mind. I mean it, Theo."},
    }},
    {key="upgrade-man_14", phase="upgrade", event="man_14", title="a band organ", building="Reindeer carousel", lines={
        {"pip", "Mrs Alder, the organ plays three tunes! I picked them all. Which one's your favourite?"},
        {"alder", "The one I can hum along to. Play it again, love, I'll find the key."},
        {"pip", "You never find the key! Not once!"},
        {"alder", "Cheek. That's why I need the organ to carry me."},
    }},
    {key="upgrade-man_15", phase="upgrade", event="man_15", title="Henrik's old apprentices come back", building="Woodcarvers' hall", lines={
        {"noelle", "Mr Strand, there's somebody at every bench! Who are they all?"},
        {"henrik", "My old apprentices. I taught them to hold a gouge. Now they correct my joints. Insufferable."},
        {"noelle", "Are you pleased? You can tell me."},
        {"henrik", "Their joints are tidy, Noelle. Yes, pleased. Mind the shavings."},
    }},
    {key="upgrade-man_16", phase="upgrade", event="man_16", title="a star for the top", building="Christmas tree", lines={
        {"theo", "Strand, I need steady hands. The star's heavy and the top branch is thin."},
        {"henrik", "Then you've trimmed it wrong. Give it here. A peg, not a nail. Always a peg."},
        {"theo", "You're lecturing a man who sells forty trees. Hold the ladder?"},
        {"henrik", "I'll hold it. You'll wobble. Try to do it gently, for the tree's sake."},
    }},
    {key="placed-reindeer_stable", phase="placed", building="reindeer_stable", lines={
        {"pip", "Noelle, will you lift the latch? I've got his supper in both pockets."},
        {"noelle", "Back up a step, Pip. He'd like the carrots without the trousers."},
    }},
    {key="placed-firework_stall", phase="placed", building="firework_stall", lines={
        {"pip", "Agnes, will you keep the key till New Year? I might want to try just one."},
        {"agnes", "In my apron, pet. You can have it when you come and fetch me to watch."},
    }},
    {key="placed-chapel", phase="placed", building="chapel", lines={
        {"agnes", "Mr Wren, will you leave the door on the latch? I'd like to hear the choir from my oven."},
        {"wren", "I'll put a wedge under it, Agnes. Hymns are apt to slam a door on the high notes."},
    }},
    {key="placed-igloo", phase="placed", building="igloo", lines={
        {"agnes", "Theo, a whole shelf for my butter? What do I owe you?"},
        {"theo", "Save me one corner of shortbread, Mrs Holt. The darker the better."},
    }},
    {key="placed-log_cabin", phase="placed", building="log_cabin", lines={
        {"finch", "Mrs Holt, have you any applewood for my first trout? Bramble's eaten all the bark off mine."},
        {"agnes", "A sack of dry chips, Mr Finch. Take the handcart. I'd like the sack back, if the goat allows."},
    }},
    {key="placed-station_kiosk", phase="placed", building="station_kiosk", resident="otis", invitation="after-46", lines={
        {"otis", "Otis Bell, with one station clock and one suitcase. Pip, which side of the counter is mine?"},
        {"pip", "You can have the stool, Mr Bell. Can I have the key?"},
        {"otis", "One turn a day, lad. Three won't bring a train any sooner. Come keep me company between trains."},
    }},
    {key="placed-post_office", phase="placed", building="post_office", lines={
        {"pip", "Noelle, could the first letter through my office be for me? I'll let you use the stamp."},
        {"noelle", "Give me an envelope, Postmaster. And turn round while I write the name."},
    }},
    {key="placed-glassblower", phase="placed", building="glassblower", resident="ada", invitation="after-71", lines={
        {"ada", "Mrs Holt? Ada Pike, off the lake boat. Is this really my furnace? I've never had a key of my own."},
        {"agnes", "Yours, love. Now, about my gingerbread dome. How big a house can you fit under one breath?"},
        {"ada", "Come by my stall with a biscuit the size of your roof, Mrs Holt. I'll see what one breath can do."},
    }},
    {key="placed-santa_workshop", phase="placed", building="santa_workshop", lines={
        {"henrik", "Pip, try the low bench. Used to be mine. Can your feet reach the rail?"},
        {"pip", "Both of them, Mr Strand! Can I carve the ears? I know what a reindeer listens with."},
    }},
    {key="placed-sleigh", phase="placed", building="sleigh", lines={
        {"rosa", "Mary, tuck that rug round your knees. When did we last go for a ride together?"},
        {"mary", "When my boots still had buckles, Rosa. Budge over. There's room for Pip."},
    }},
    {key="visit-station_kiosk-placed-station_kiosk", phase="visit", building="station_kiosk", checkpoint="placed-station_kiosk", level=46, prompt="Ask Otis", choices={
        {key="visit-station_kiosk-placed-station_kiosk.personal", topic="personal", label="How do you pass the time?", lines={
            {"pip", "What do you do when the train's late, Mr Bell? I've counted every nail in this bench."},
            {"otis", "Turn my lunch tin over, Pip. Dad scratched a board in the lid. Six coat buttons each. You pick."},
            {"pip", "I'll take the brass ones. Show me which way they go?"},
        }},
        {key="visit-station_kiosk-placed-station_kiosk", topic="story", label="Can I wind it alone?", lines={
            {"pip", "Will you listen while I wind it, Mr Bell? What if I give it one turn too many?"},
            {"otis", "Rest your thumb against mine, Pip. Feel it push back? Now you know where to stop."},
        }},
    }},
    {key="visit-station_kiosk-after-63", phase="visit", building="station_kiosk", checkpoint="after-63", level=63, prompt="Ask Otis", choices={
        {key="visit-station_kiosk-after-63.personal", topic="personal", label="Why keep that dent?", lines={
            {"pip", "Mr Bell, shall I knock that dent out of your lunch tin? Mr Strand lent me a little mallet."},
            {"otis", "Leave it, Pip. Dad sat on it the first time I beat him. Only trophy I ever won."},
        }},
        {key="visit-station_kiosk-after-63", topic="story", label="How long should a letter take?", lines={
            {"pip", "How long would you need to read one little letter, Mr Bell?"},
            {"otis", "Depends who wrote it, Pip. I've one from my dad I still take out on my tea break."},
        }},
    }},
    {key="visit-station_kiosk-after-94", phase="visit", building="station_kiosk", checkpoint="after-94", level=94, prompt="Ask Otis", choices={
        {key="visit-station_kiosk-after-94.personal", topic="personal", label="Can Mum play too?", lines={
            {"pip", "Mum plays draughts, Mr Bell. Could we have a game here while the kettle boils?"},
            {"otis", "Here's my tin lid and a pocketful of buttons. I'll pour the tea and advise whoever's losing."},
        }},
        {key="visit-station_kiosk-after-94", topic="story", label="Can Mum wind the clock?", lines={
            {"pip", "Mr Bell, could I show Mum how to wind the clock tomorrow?"},
            {"otis", "I'll leave the key with you, Pip. Tell her I'm taking my first lie-in since you walked in here."},
        }},
    }},
    {key="visit-glassblower-placed-glassblower", phase="visit", building="glassblower", checkpoint="placed-glassblower", level=71, prompt="Ask Ada", choices={
        {key="visit-glassblower-placed-glassblower.personal", topic="personal", label="What did you make first?", lines={
            {"pip", "What was the first thing you blew, Ada?"},
            {"ada", "A marble. I was aiming for a vase. Here, Pip. You can try it on the cobbles."},
        }},
        {key="visit-glassblower-placed-glassblower", topic="story", label="Where will you keep the key?", lines={
            {"agnes", "Ada, shall I keep your furnace key on my hook overnight?"},
            {"ada", "Under my pillow tonight, Mrs Holt. In the morning I want to reach for it and find it's mine."},
        }},
    }},
    {key="visit-glassblower-after-74", phase="visit", building="glassblower", checkpoint="after-74", level=74, prompt="Ask Ada", choices={
        {key="visit-glassblower-after-74.personal", topic="personal", label="Do you bake too?", lines={
            {"agnes", "Do you bake at home, Ada?"},
            {"ada", "I tried your gingerbread men. I kept turning the tray like a blowing iron. They lost their hats."},
        }},
        {key="visit-glassblower-after-74", topic="story", label="Why give the dome feet?", lines={
            {"agnes", "Ada, why did you give my gingerbread dome three little glass feet?"},
            {"ada", "Put your nose down here, Mrs Holt. What's the use of a whole gingerbread house nobody can smell?"},
        }},
    }},
    {key="visit-glassblower-after-84", phase="visit", building="glassblower", checkpoint="after-84", level=84, prompt="Ask Ada", choices={
        {key="visit-glassblower-after-84.personal", topic="personal", label="Do you play an instrument?", lines={
            {"noelle", "Have you ever played in a band, Ada?"},
            {"ada", "Only the spoons. Lend me two and hum that waltz. I'll come in when you nod."},
        }},
        {key="visit-glassblower-after-84", topic="story", label="How far does the bell carry?", lines={
            {"ada", "Noelle, could you ring the bell for me? I only ever hear my glass from the bench."},
            {"noelle", "Go stand on Gran's step, Ada. You can hear it clear over there. Wave when you want me to ring."},
        }},
    }},
    {key="visit-glassblower-after-89", phase="visit", building="glassblower", checkpoint="after-89", level=89, prompt="Ask Ada", choices={
        {key="visit-glassblower-after-89.personal", topic="personal", label="What warms your hands?", lines={
            {"pip", "Ada, what do you put in your pockets when you're out here in the cold?"},
            {"ada", "A baked potato in each. You can have the left one. I've butter in my lunch tin."},
        }},
        {key="visit-glassblower-after-89", topic="story", label="Can I help shelter the lamp?", lines={
            {"pip", "Ada, if I cup my hands round the station lamp, will that help?"},
            {"ada", "Put them in your pockets, Pip. I made the glass to do that job. You keep ten warm fingers."},
        }},
    }},
    {key="visit-glassblower-after-94", phase="visit", building="glassblower", checkpoint="after-94", level=94, prompt="Ask Ada", choices={
        {key="visit-glassblower-after-94.personal", topic="personal", label="Where would you go by train?", lines={
            {"mary", "If I bought you a ticket, Ada, where would you get off?"},
            {"ada", "The seaside. I've never seen the green glass the waves turn smooth. I'd fill both pockets."},
        }},
        {key="visit-glassblower-after-94", topic="story", label="Could Mary see the lamp?", lines={
            {"mary", "Ada, Pip says you'd trade a whole pocketful of glass for a minute on the footplate. Is that true?"},
            {"ada", "I'd settle for the view from your carriage, Mary. Could you see the lamp from the bend?"},
            {"mary", "Small as a shirt button. I had my coat on before the brakes squeaked."},
        }},
    }},
    {key="visit-glassblower-after-100", phase="visit", building="glassblower", checkpoint="after-100", level=100, prompt="Ask Ada", choices={
        {key="visit-glassblower-after-100.personal", topic="personal", label="Will you teach me?", lines={
            {"pip", "When I'm tall enough, Ada, will you teach me to blow glass?"},
            {"ada", "Let's start today. Pick a colour for your first marble. You can reach that shelf just fine."},
        }},
        {key="visit-glassblower-after-100", topic="story", label="Will you stay for January?", lines={
            {"noelle", "Ada, I'm ordering a bell for my own front door. Will you still be here in January?"},
            {"ada", "Knock in the morning, Noelle. The key lives on a hook now. I sleep better without it in my ear."},
        }},
    }},
    {key="meeting-station_kiosk-glassblower", phase="meeting", sites={"station_kiosk", "glassblower"}, level=71, lines={
        {"otis", "Miss Pike, could you make me a blue draughts button? A brass one went down the platform drain."},
        {"ada", "Lend me the lid of your lunch tin, Mr Bell. I want to see what size your squares are."},
        {"otis", "Here you go. Mind the dent. That's the only square where a man can hide from a king."},
        {"ada", "Then I'll take blue. You can teach me that move when I bring your button back."},
    }, replies={
        {index=3, building="station_kiosk", when="visit-station_kiosk-after-63.personal", line={"otis", "That's Dad's dent. Pip offered to mend it, but I beat Dad fair and square. It's staying."}},
        {index=4, building="station_kiosk", when="visit-station_kiosk-after-63.personal", line={"ada", "Then the dent stays. I'll bring the blue button after work. Will you teach me on that board?"}},
    }, followups={
        {key="meeting-station_kiosk-glassblower.glassblower", building="glassblower", when="meeting-station_kiosk-glassblower", topic="meeting", label="Who won your first game?", lines={
            {"pip", "Did your blue button bring you luck against Mr Bell, Ada?"},
            {"ada", "I won, Pip. Jumped his last two buttons. I could hear my blue one ring on the tin both times."},
        }},
        {key="meeting-station_kiosk-glassblower.station_kiosk", building="station_kiosk", when="meeting-station_kiosk-glassblower", topic="meeting", label="How did you fare against Ada?", lines={
            {"pip", "Who won that first game on your tin lid, Mr Bell?"},
            {"otis", "Miss Pike did. I taught her how to jump two men and left mine in a lovely straight line."},
            {"pip", "Will you teach me that way too, Mr Bell?"},
        }},
        {key="meeting-station_kiosk-glassblower.glassblower.reply", building="glassblower", when="meeting-station_kiosk-glassblower", topic="meeting", source="Otis", heard_any={"meeting-station_kiosk-glassblower.station_kiosk", "meeting-station_kiosk-glassblower.station_kiosk.reply"}, label="Did Otis leave you that jump?", lines={
            {"pip", "Mr Bell says he left his buttons in a line. Did he mean for you to win, Ada?"},
            {"ada", "He asked for his turn back, Pip. My blue button had rung twice on the tin. Both men were mine."},
            {"ada", "He's asked me to put felt on the bottom. Says a fellow ought to be able to lose in peace."},
        }},
        {key="meeting-station_kiosk-glassblower.station_kiosk.reply", building="station_kiosk", when="meeting-station_kiosk-glassblower", topic="meeting", source="Ada", heard_any={"meeting-station_kiosk-glassblower.glassblower", "meeting-station_kiosk-glassblower.glassblower.reply"}, label="Did you hear Ada's button ring?", lines={
            {"pip", "Ada heard two pings when she won. What did they sound like from your end, Mr Bell?"},
            {"otis", "School bell, Pip. I taught her the double jump, left two men in a row and got a lesson myself."},
            {"otis", "Bring your buttons at dinner. Let's see if I've learned it."},
        }},
    }},
}
